def walk(o, prefix='', depth=0):
    if isinstance(o, dict):
        print(prefix, 'dict keys:', list(o.keys()))
        if depth < 3:
            for k, v in o.items():
                walk(v, prefix + '.' + k, depth+1)
    elif isinstance(o, list):
        print(prefix, 'list len', len(o), 'elem type', type(o[0]).__name__ if o else '-')
        if o and depth < 3 and not isinstance(o[0], (int, str)):
            walk(o[0], prefix + '[0]', depth+1)
        elif o and isinstance(o[0], str):
            print(prefix, '[0]=', o[0][:120])
    else:
        s = str(o)
        print(prefix, '=', s[:150], ('... len='+str(len(s))) if len(s) > 150 else '')
